import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, vec4, float, mix, uniform, positionLocal, MeshStandardNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Object3D();
  group.name = 'photo-hero-composite';
  group.position.set(0, 0, 0);

  const colors = {
    background: '#0b0b10',
    accent: '#ff2a38',
    paper: '#e8ecf2',
  };

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorTex = ctx.textureLoader(imageUrl);
  const depthTex = ctx.textureLoader(depthUrl);
  colorTex.colorSpace = THREE.SRGBColorSpace;

  const W = 4.0, H = 2.5;
  const geometry = new THREE.PlaneGeometry(W, H, 64, 64);

  const dispAmount = uniform(0.18);
  const parallaxOffset = uniform(vec2(0, 0));

  const dMap = texture(depthTex, uv());
  const dispUv = uv().add(parallaxOffset.mul(dMap.r));
  const dispSample = texture(depthTex, dispUv).r;

  const displaced = positionLocal.add(vec3(0, 0, dispSample.sub(0.5).mul(dispAmount)));

  const baseColor = texture(colorTex, dispUv);

  // filmic grade: lift blacks, shoulder highlights, contrast, desat preserving red
  const lifted = mix(vec3(0.051, 0.051, 0.071), baseColor.rgb, baseColor.rgb);
  const contrast = lifted.sub(0.5).mul(1.12).add(0.5);
  const luma = contrast.r.mul(0.299).add(contrast.g.mul(0.587)).add(contrast.b.mul(0.114));
  const desatG = mix(luma, contrast.g, 0.92);
  const desatB = mix(luma, contrast.b, 0.92);
  const gradedColor = vec3(contrast.r, desatG, desatB);

  // rim light along silhouette using depth gradient approximation
  const rim = float(1.0).sub(dMap.r).mul(0.02);
  const finalColor = gradedColor.add(vec3(rim, rim, rim).mul(0.3));

  const material = new MeshStandardNodeMaterial();
  material.positionNode = displaced;
  material.colorNode = vec4(finalColor, 1.0);
  material.roughness = 0.6;
  material.metalness = 0.1;

  const plate = new THREE.Mesh(geometry, material);
  plate.name = 'plate';
  plate.material.transparent = true;
  plate.material.opacity = 0;
  group.add(plate);

  // bottom scrim gradient
  const scrimGeo = new THREE.PlaneGeometry(W, H);
  const scrimMat = new THREE.MeshBasicNodeMaterial();
  const scrimUv = uv();
  const scrimAlpha = scrimUv.y.smoothstep(1.0, 0.45).oneMinus().clamp(0, 1);
  scrimMat.colorNode = vec4(0.043, 0.043, 0.063, scrimAlpha.mul(0.92));
  scrimMat.transparent = true;
  const scrim = new THREE.Mesh(scrimGeo, scrimMat);
  scrim.position.z = 0.001;
  scrim.name = 'scrim';
  group.add(scrim);

  // caption block
  const captionGroup = new THREE.Object3D();
  captionGroup.name = 'caption-block';
  const padX = -W / 2 + 0.5;
  const baseY = -H / 2 + 0.5;

  const kickerMesh = createTextMesh(ctx.fontAtlas, {
    text: 'NOVA ATELIER / GENEVA',
    fontFamily: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 9,
    letterSpacing: 0.12,
    color: colors.paper,
  });
  kickerMesh.position.set(padX, baseY + 0.5, 0.01);
  captionGroup.add(kickerMesh);

  const headlineMesh = createTextMesh(ctx.fontAtlas, {
    text: 'Time, Machined.',
    fontFamily: 'Lora',
    fontWeight: 600,
    fontSize: 34,
    letterSpacing: -0.01,
    color: colors.paper,
  });
  headlineMesh.position.set(padX, baseY + 0.25, 0.01);
  captionGroup.add(headlineMesh);

  const hairline = new THREE.Mesh(
    new THREE.PlaneGeometry(0.75, 0.02),
    new THREE.MeshBasicMaterial({ color: colors.accent, toneMapped: false })
  );
  hairline.position.set(padX + 0.375, baseY + 0.13, 0.01);
  captionGroup.add(hairline);

  const bodyMesh = createTextMesh(ctx.fontAtlas, {
    text: 'Every case begins as a single billet of 904L steel.',
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 13,
    color: colors.paper,
  });
  bodyMesh.position.set(padX, baseY, 0.01);
  captionGroup.add(bodyMesh);

  const captionMesh = createTextMesh(ctx.fontAtlas, {
    text: 'CALIBRE NA-01 / 72 HOUR RESERVE',
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 9,
    letterSpacing: 0.12,
    color: colors.paper,
  });
  captionMesh.position.set(padX, baseY - 0.25, 0.01);
  captionGroup.add(captionMesh);

  captionGroup.position.y -= 0.4;
  group.add(captionGroup);

  // apply cinematic primitive: parallax-scroll
  ctx.primitives['parallax-scroll'](group, { intensity: 0.35 });

  // animations
  const timelines = [];

  const plateTl = gsap.to(plate.material, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  timelines.push(plateTl);

  const captionTl = gsap.to(captionGroup.position, {
    y: captionGroup.position.y + 0.4,
    duration: 0.7,
    delay: 0.12,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });
  timelines.push(captionTl);

  // scroll-driven parallax depth handler
  const onScroll = (scrollValue) => {
    const s = typeof scrollValue === 'number' ? scrollValue : 0;
    parallaxOffset.value.set(0, s * 0.14);
  };

  group.userData.handlers = {
    onScroll,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    geometry.dispose();
    material.dispose();
    scrimGeo.dispose();
    scrimMat.dispose();
    hairline.geometry.dispose();
    hairline.material.dispose();
    [kickerMesh, headlineMesh, bodyMesh, captionMesh].forEach((m) => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
    });
  };

  return group;
}
